  // 3.0: Simple help and the install-statistics question
  'simple.help.g1.title': 'Connecter un écran',
  'simple.help.g1.s1': 'Sur la télévision, la tablette ou l’ordinateur que vous voulez utiliser, ouvrez le lecteur : installez l’app Android, ou ouvrez la page /player de ce site dans son navigateur.',
  'simple.help.g1.s2': 'Pas de télévision sous la main ? Ouvrez le lecteur dans un autre onglet du navigateur pour essayer.',
  'simple.help.g1.s3': 'Le lecteur affiche un code à 6 chiffres. Ici, choisissez « Ajouter un écran » et saisissez-le.',
  'simple.help.g1.s4': 'Donnez à l’écran un nom que vous reconnaîtrez, par exemple « Vitrine ».',
  'simple.help.g2.title': 'Changer ce qu’affiche un écran',
  'simple.help.g2.s1': 'Choisissez « Changer ce qu’affiche un écran » ou touchez l’écran sous « Vos écrans ».',
  'simple.help.g2.s2': 'Choisissez « Remplacer » pour n’afficher que les nouveautés, ou « Ajouter » pour garder ce qui passe déjà.',
  'simple.help.g2.s3': 'Importez des photos ou des vidéos, choisissez-en parmi celles déjà importées, ou affichez la même chose qu’un autre écran.',
  'simple.help.g2.s4': 'L’écran se met à jour en quelques secondes.',
  'simple.help.g3.title': 'Importer des photos et des vidéos',
  'simple.help.g3.s1': 'Choisissez « Téléverser des photos » et sélectionnez autant de fichiers que vous voulez, ou faites-les glisser.',
  'simple.help.g3.s2': 'Cochez les écrans qui doivent les afficher, ou décochez-les tous pour les garder pour plus tard.',
  'simple.help.g3.s3': 'Chaque photo s’affiche 10 secondes ; les vidéos sont lues jusqu’au bout.',
  'simple.help.q1': 'Que puis-je utiliser comme écran ?',
  'simple.help.a1': 'Les téléviseurs Android, boîtiers TV et tablettes, Fire TV, téléviseurs connectés LG et Samsung, Raspberry Pi, Windows et ChromeOS, ou tout appareil doté d’un navigateur web.',
  'simple.help.q2': 'Mon écran ne change pas. Que dois-je vérifier ?',
  'simple.help.a2': 'Vérifiez que l’écran indique « En lecture » sur la page d’accueil. S’il indique « Hors ligne », vérifiez que l’appareil est allumé et connecté à internet ; il récupère vos changements dès qu’il se reconnecte.',
  'simple.help.q3': 'Que se passe-t-il si internet tombe ?',
  'simple.help.a3': 'Les écrans gardent le contenu en local et continuent de le lire. Les nouveaux changements arrivent quand la connexion revient.',
  'simple.help.q4': 'Quels fichiers puis-je importer ?',
  'simple.help.a4': 'Des photos (JPEG, PNG, GIF, WebP) et des vidéos (le MP4 fonctionne le mieux), ainsi que de l’audio. Les PDF s’importent depuis la page Contenu dans la vue « Avancé ».',
  'simple.help.q5': 'Comment renommer ou retirer un écran ?',
  'simple.help.a5': 'Passez en « Avancé » (en haut à droite), ouvrez « Écrans », cliquez sur l’écran, puis utilisez Renommer ou Retirer en haut de sa page.',
  'simple.help.q6': 'Puis-je afficher des choses différentes selon l’heure ?',
  'simple.help.a6': 'Oui : c’est « Calendrier », dans la vue « Avancé ». La vue simple affiche toujours le même contenu sur un écran jusqu’à ce que vous le changiez.',
  'simple.help.trial_q': 'Comment fonctionne l’essai gratuit ?',
  'simple.help.trial_a': 'Vous profitez de 14 jours du plan Pro avec toutes les fonctionnalités, sans carte bancaire. À la fin, vous passez au plan Free : rien n’est supprimé, et les écrans au-delà de la limite du plan Free sont mis en pause jusqu’à ce que vous choisissiez un plan.',
  'stats.prompt.title': 'Nous aider à savoir combien ScreenTinker est utilisé ?',
  'stats.prompt.body': 'Comme la plupart des installations sont privées, nous ne savons pas combien d’écrans existent. Le partage envoie un identifiant aléatoire, la version et le nombre de vos écrans, rien d’autre, jamais. Vous pouvez changer cela à tout moment dans les Paramètres.',
  'stats.prompt.share': 'Partager',
  'stats.prompt.no': 'Non merci',
  'stats.prompt.thanks': 'Merci : les statistiques d’installation sont partagées',
