  'exp.how_title': 'Comment le résultat est calculé',
  'exp.how_1': 'Ce que chaque écran a réellement diffusé provient des preuves de diffusion : un écran éteint n’est donc pas compté comme affichant quoi que ce soit. Une heure ne compte pour une version que si cette version était la seule à l’écran.',
  'exp.how_2': 'Par lieu, chaque magasin est comparé à ses propres ventes habituelles d’avant le test : un grand magasin ne gagne donc pas simplement parce qu’il est grand. Selon l’heure, les versions se relaient et tournent au fil de la semaine : aucune version n’obtient toutes les heures d’affluence.',
  'exp.how_3': 'La fourchette affichée (l’intervalle à 95 %) provient d’un rééchantillonnage de jours entiers ou de magasins entiers, 2 000 fois. Quand elle ne contient pas zéro, la différence est probablement réelle. « Encore environ N jours » est une estimation du temps nécessaire pour que la fourchette soit assez étroite pour trancher.',
  'exp.privacy': 'Confidentialité : seuls des totaux par heure, magasin et article sont importés depuis votre caisse. Aucune donnée de client, de commande, de carte ou de ticket n’est jamais lue ni stockée.',
