  'sitecache.how': 'Les écrans vérifient chaque fichier à l’aide de son empreinte et reviennent à ce serveur si le cache est lent, en panne ou incorrect : un cache peut donc économiser de la bande passante, mais jamais laisser un écran noir. Les lecteurs web l’utilisent dès leur prochain redémarrage ; les lecteurs Android dès leur prochaine mise à jour de liste de lecture. Voir docs/site-cache.md.',
