  'migrate.how.xibo': 'Dans Xibo, ouvrez Administration, puis Applications, et ajoutez une application avec « Client Credentials » coché. Copiez son Client ID et son Client Secret. Saisissez l’adresse de votre CMS (celle où vous vous connectez), par exemple https://cms.example.com.',
  'migrate.how.yodeck': 'Dans Yodeck, ouvrez Account Settings, Advanced Settings, API Tokens, et générez un jeton (forfait Premium ou Enterprise). Collez-le sous la forme libellé:jeton. Yodeck ne fournit pas via son API les images et documents d’origine téléversés : ils sont listés pour que vous puissiez les ajouter avec l’import zip. Les vidéos sont récupérées dans la version que Yodeck diffuse.',
  'migrate.how.optisigns': 'OptiSigns a une API, mais elle ne documente aucun moyen de télécharger vos fichiers : une liste de lecture arriverait donc vide. Téléchargez vos fichiers depuis OptiSigns et utilisez l’import zip : un dossier par liste de lecture, ou un fichier playlists.csv.',
  'migrate.how.screencloud': 'Dans ScreenCloud Studio, ouvrez Account Settings, puis l’onglet Developer, et créez un jeton avec des droits de lecture. Choisissez la région indiquée (EU ou US). ScreenCloud conserve les règles horaires sur les éléments de chaque chaîne ; elles sont listées, pas importées.',
  'migrate.how.anthias': 'Saisissez l’adresse de votre appareil Anthias, par exemple http://192.168.1.20. Si vous avez activé l’authentification, saisissez son nom d’utilisateur et son mot de passe. Chaque appareil est importé comme un écran avec une liste de lecture.',
  'migrate.how.screenly': 'Dans Screenly, ouvrez Settings, Security, Tokens et ajoutez un jeton. Les listes de lecture, étiquettes et écrans sont transférés ; les règles simples de jour et d’heure deviennent des calendriers.',
  'migrate.how.generic_zip': 'Téléversez un zip de vos médias. Chaque dossier devient une liste de lecture. Ajoutez si vous le souhaitez playlists.csv (colonnes : playlist, file, duration, order) et screens.csv (colonnes : name, group, playlist).',
